class NumberSequence:
    def __init__(self, start, end):
        self.current = start
        self.end = end

    def __iter__(self):
        return self

    def __next__(self):
        if self.current > self.end:
            raise StopIteration
        else:
            val = self.current
            self.current += 1
            return val

# Example usage:
# for num in NumberSequence(1, 3):
#     print(num) # Output: 1, 2, 3
